import { Component, inject, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators, ReactiveFormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { CommonModule } from '@angular/common';
import { UsuarioService } from '../../../controllers/usuario.service';

@Component({
  selector: 'app-recover-password',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './recover-password.html'
})
export class RecoverPassword implements OnInit {
  recoverForm!: FormGroup;
  loading = false;
  success = false;
  error: string | null = null;

  private fb = inject(FormBuilder);
  private router = inject(Router);
  private usuarioService = inject(UsuarioService);
  
  ngOnInit(): void {
    this.recoverForm = this.fb.group({
      rfc: ['', [Validators.required]]
    });
  }

  async onSubmit(): Promise<void> {
    if (this.recoverForm.invalid) {
      return;
    }
    this.loading = true;
    this.success = false;
    this.error = null;
    try {
      const { rfc } = this.recoverForm.value;
      const response = await this.usuarioService.sendPasswordResetLink(rfc);
      if (response?.status === false) {
        this.success = false;
        this.error ='Ocurrió un error al enviar el correo.';
        return;
      }
      this.success = true;
    } catch {
      this.success = false;
      this.error = 'Ocurrió un error al enviar el correo de recuperación.';

    } finally {
      this.loading = false;
    }
  }

  retry(): void {
    this.error = null;
    this.success = false;  
   }
  goToLogin(): void {
    this.router.navigate(['/']);
  }
}
