import { Component, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, RouterLink } from '@angular/router';
import { AuthService } from '../../services/auth.service';
import { LoginCredentials } from '../../models/login-credentials';
import { environment } from '../../../../environments/environment';
import { TramiteService } from '../../../controllers/tramite.service';

@Component({
  selector: 'app-login',
  standalone: true,
  imports: [
    FormsModule,
    RouterLink,
    CommonModule,
  ],
  templateUrl: './login.html',
  styleUrl: './login.css'
})
export class Login {
  rfc = ''
  password = ''
  loading = false

  app_name = environment.app_name

  //services
  private router = inject(Router);
  private tramiteService = inject(TramiteService);
  private authService = inject(AuthService);
  hidePassword = true;

  // ... constructor y otros métodos como ngOnInit()

  // Método para alternar la visibilidad
  togglePasswordVisibility(): void {
    this.hidePassword = !this.hidePassword;
  }

  public async submit() {
    this.loading = true;

    try {
      const credentials: LoginCredentials = {
        rfc: this.rfc.toUpperCase(),
        password: this.password
      };
      const result = await this.authService.login(credentials);

      if (result) {
        if (result.user.user_type === 'EXTERNO') {
          if (await this.tramiteService.usuarioLogeadoTieneTramite()) {
            this.router.navigate(['/main/externos/status-tramite']);
            return;
          }
          this.router.navigate(['/main/externos/inicio']);
          return;
        }
        this.router.navigate(['/main/inicio']);
      }
    } catch (error) {
      console.error('Error en login:', error);
    } finally {
      this.loading = false;
    }
  }
}
