import { Component, inject, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators, ReactiveFormsModule } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { CommonModule } from '@angular/common';
import { UsuarioService } from '../../../controllers/usuario.service'; // Adjusted path

@Component({
  selector: 'app-reset-password',
  standalone: true,
  imports: [CommonModule, ReactiveFormsModule],
  templateUrl: './reset-password.html'
})
export class ResetPassword implements OnInit {
  resetForm!: FormGroup;
  loading = false;
  success = false;
  error: string | null = null;
  token: string | null = null;
  email: string | null = null;
  private fb = inject(FormBuilder);
  private activatedRoute = inject(ActivatedRoute)
  private router = inject(Router);
  private usuarioService = inject(UsuarioService);
 
  ngOnInit(): void {
    this.token = this.activatedRoute.snapshot.paramMap.get('token');

    this.resetForm = this.fb.group({
      password: ['', [Validators.required, Validators.minLength(8)]],
      password_confirmation: ['', [Validators.required]]
    }, { validator: this.passwordMatchValidator });
  }

  passwordMatchValidator(frm: FormGroup) {
    return frm.get('password')?.value === frm.get('password_confirmation')?.value
      ? null : { 'mismatch': true };
  }

  async onSubmit(): Promise<void> {
    if (this.resetForm.invalid) {
      return;
    }
    this.loading = true;
    this.success = false;
    this.error = null;

    try {
      const { password, password_confirmation } = this.resetForm.value;
      if (!this.token) {
        throw new Error('Token de restablecimiento no encontrado.');
      }
      const response = await this.usuarioService.resetPassword(this.token, password, password_confirmation);
      if (response?.status === false) {
        this.error = 'Ocurrió un error al restablecer la contraseña.';
        return;
      }
      this.success = true;
    } catch {
      this.error =  'Ocurrió un error al restablecer la contraseña.';
    } finally {
      this.loading = false;
    }
  }

  goToLogin(): void {
    this.router.navigate(['/']);
  }
}